  values ('strike-tee-black-blue', 'MV-01', 'Strike Tee', 'Black / Blue', (select id from categories where handle = 'tees'), 25000, 'published', true, true, 'TEE', 'Drip-lettered MAVERICK on the front, the slogan stacked across the back.', 'MAVERICK in electric-blue drip lettering with a white outline across the chest. On the back, DIFFERENT BY CHOICE. stacked large in the same treatment, with a distressed, hand-pulled finish.', array['Black body','Electric blue + white print','Front and back print','Distressed finish','Oversized, boxy fit']::text[], '/garments/strike-black-front.png', '/garments/strike-black-front-tight.png', '/garments/strike-black-back.png', '/garments/strike-black-back-tight.png', '/garments/strike-black-side.png', '/garments/strike-black-side-tight.png', 0);
  values ('layered-long-sleeve', 'MV-02', 'Layered Long Sleeve', 'Black', (select id from categories where handle = 'long-sleeves'), 32000, 'published', true, true, 'LONG SLEEVE', 'Lightning wordmark on the chest, slogan on the lower back and both cuffs.', 'The MAVERICK lightning wordmark across the chest and a small M logo at the hem. DIFFERENT BY CHOICE. runs low across the back and repeats on both cuffs. Layered sleeves give the look of a tee over a long sleeve.', array['Black body','White print','Front, back and cuff prints','Layered-look sleeves']::text[], '/garments/layered-longsleeve-front.png', '/garments/layered-longsleeve-front-tight.png', '/garments/layered-longsleeve-back.png', '/garments/layered-longsleeve-back-tight.png', null, null, 1);
  values ('peel-tee-white', 'MV-03', 'Peel Tee', 'White', (select id from categories where handle = 'tees'), 28000, 'published', false, true, 'TEE', 'The red MA box peels away to reveal the eye and the electrified skeleton.', 'A full-colour illustrated front. The red MA box peels down off the wordmark to show an eye and an electrified skeleton underneath, with Different By Choice set in red beside it.', array['White body','Full-colour illustrated print','Front print','Oversized, boxy fit']::text[], '/garments/peel-front.png', '/garments/peel-front-tight.png', null, null, null, null, 2);
  values ('horned-m-ringer', 'MV-04', 'Horned M Ringer', 'Black / Red', (select id from categories where handle = 'ringers'), 25000, 'published', false, false, 'RINGER', 'The horned M on the chest, framed by a red ringer collar and cuffs.', 'A clean black ringer with red rib at the collar and sleeves. The horned M sits on the left chest. Quiet from a distance, unmistakable up close.', array['Black body','Red rib collar and cuffs','White chest logo','Regular fit']::text[], '/garments/horned-ringer-front.png', '/garments/horned-ringer-front-tight.png', null, null, null, null, 3);
  values ('strike-tee-white-yellow', 'MV-05', 'Strike Tee', 'White / Yellow', (select id from categories where handle = 'tees'), 25000, 'published', false, true, 'TEE', 'The Strike tee in white, with yellow drip lettering and a black outline.', 'The Strike graphics in reverse: yellow drip lettering with a heavy black outline on a white body. MAVERICK across the front, DIFFERENT BY CHOICE. stacked across the back.', array['White body','Yellow + black print','Front and back print','Distressed finish','Oversized, boxy fit']::text[], '/garments/strike-white-front.png', '/garments/strike-white-front-tight.png', '/garments/strike-white-back.png', '/garments/strike-white-back-tight.png', '/garments/strike-white-side.png', '/garments/strike-white-side-tight.png', 4);
  values ('lone-star-ringer', 'MV-06', 'Lone Star Ringer', 'Black / Red', (select id from categories where handle = 'ringers'), 28000, 'published', false, false, 'RINGER', 'Varsity front stack, with a full star M across the back.', 'A varsity-style front: boxed MAVERICK, Different by Choice, and the M set into a red star with a signature underneath. The back carries the star M at full size.', array['Black body','Red rib collar and cuffs','Front and back print','Regular fit']::text[], '/garments/star-ringer-front.png', '/garments/star-ringer-front-tight.png', '/garments/star-ringer-back.png', '/garments/star-ringer-back-tight.png', null, null, 5);

